import{_t as e,it as t,n,rt as r}from"./chunks/framework.CdvHacad.js";var i=JSON.parse(`{"title":"Algorithm Support","description":"","frontmatter":{"packageVersion":"0.16.0"},"headers":[],"relativePath":"reference/algorithms.md","filePath":"site/reference/algorithms.md","lastUpdated":1792852428000}`),a={name:`reference/algorithms.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="algorithm-support" tabindex="-1">Algorithm Support <a class="header-anchor" href="#algorithm-support" aria-label="Permalink to “Algorithm Support”">​</a></h1><p>Certificate parsing, certificate issuance, key operations, and signature verification have separate support. Certificate issuance takes a caller supplied WebCrypto public key and a signing private key. The signing key must use a signature algorithm supported by micro509.</p><h2 id="certificate-and-key-capabilities" tabindex="-1">Certificate and key capabilities <a class="header-anchor" href="#certificate-and-key-capabilities" aria-label="Permalink to “Certificate and key capabilities”">​</a></h2><table tabindex="0"><thead><tr><th>Algorithm / key type</th><th style="text-align:center;">Certificate parsing</th><th style="text-align:center;">Certificate issuance as subject key</th><th style="text-align:center;">Generate / import through micro509</th><th style="text-align:center;">Sign / verify signatures</th><th style="text-align:center;">Key agreement</th><th style="text-align:center;">Key encapsulation</th></tr></thead><tbody><tr><td>RSA signatures</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td></tr><tr><td>RSA-OAEP</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td><td style="text-align:center;">yes</td></tr><tr><td>ECDSA P-256/P-384/P-521</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td></tr><tr><td>Ed25519</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td></tr><tr><td>X25519</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes, with an exportable caller key</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td></tr><tr><td>Ed448</td><td style="text-align:center;">yes</td><td style="text-align:center;">runtime dependent<sup class="footnote-ref"><a href="#footnote1">[1]</a><a class="footnote-anchor" id="footnote-ref1"></a></sup></td><td style="text-align:center;">no</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td></tr><tr><td>X448</td><td style="text-align:center;">yes</td><td style="text-align:center;">runtime dependent<sup class="footnote-ref"><a href="#footnote1">[1:1]</a><a class="footnote-anchor" id="footnote-ref1:1"></a></sup></td><td style="text-align:center;">no</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td></tr></tbody></table><p>RSA signature support covers PKCS#1 v1.5 and RSA-PSS. RSA-OAEP supports SHA-256/384/512 hashes and an optional label. Explicit OAEP key imports also accept <code>hash: &#39;SHA-1&#39;</code> for legacy envelopes. SHA-256 is the default. SHA-1 is unavailable for key generation and RSA signature imports. The <code>yes</code> values for ECDSA and Ed25519 cover those signature algorithms. <code>verifySignatureWithKey</code> verifies with an existing WebCrypto public key, including a non-extractable key. Certificate verification uses the same supported signature algorithms. Ed25519, Ed448, X25519 and X448 certificate key-usage rules follow <a href="https://www.rfc-editor.org/rfc/rfc9295.html" target="_blank" rel="noreferrer">RFC 9295</a>. A certificate using a key type without a supported signature operation can still be issued with that subject key when the runtime can export it and a supported CA signs it. An X25519 certificate can participate in <code>verifyCertificateChain</code>: path verification checks the issuer signature and certificate rules, without performing X25519.</p><p>Generic SPKI and PKCS#8 export functions delegate to WebCrypto and can export other key types when the supplied <code>CryptoKey</code> is extractable and its runtime supports the format. micro509 key import and generation are narrower.</p><p>DSA and Brainpool signing and verification are unsupported. micro509 also has no ECDH key generation/import or key-agreement API.</p><h2 id="key-formats" tabindex="-1">Key formats <a class="header-anchor" href="#key-formats" aria-label="Permalink to “Key formats”">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th style="text-align:center;">Import through micro509</th><th style="text-align:center;">Export through micro509</th></tr></thead><tbody><tr><td>PKCS#8</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td></tr><tr><td>SPKI</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td></tr><tr><td>JWK</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td></tr><tr><td>PKCS#1 (RSA)</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td></tr><tr><td>SEC1 (EC)</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td></tr></tbody></table><h2 id="packaged-symmetric-operations" tabindex="-1">Packaged symmetric operations <a class="header-anchor" href="#packaged-symmetric-operations" aria-label="Permalink to “Packaged symmetric operations”">​</a></h2><p>micro509 has no general-purpose symmetric encryption, MAC, or KDF API. These primitives are available only inside higher-level format workflows:</p><table tabindex="0"><thead><tr><th>Workflow</th><th>Packaged operations</th></tr></thead><tbody><tr><td>Encrypted PKCS#8 / PFX</td><td>PBES2, AES-CBC, PBKDF2 with HMAC-SHA1 or HMAC-SHA256</td></tr><tr><td>Legacy encrypted PEM</td><td>AES-128-CBC, AES-192-CBC, AES-256-CBC</td></tr><tr><td>PKCS#12 MAC</td><td>PKCS#12 KDF and HMAC-SHA-256</td></tr><tr><td>PBMAC1 (<a href="https://www.rfc-editor.org/rfc/rfc9879.html" target="_blank" rel="noreferrer">RFC 9879</a>)</td><td>PBKDF2 HMAC-SHA-256/384/512 and HMAC-SHA-256/384/512</td></tr></tbody></table><p>PBMAC1 creation uses SHA-256.</p><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="footnote1" class="footnote-item"><p>Issuance depends on the WebCrypto runtime providing an exportable key. micro509 enforces the certificate key-usage rules. micro509 has no generation or import API for these algorithms. It does not perform X25519/X448 agreement. <a href="#footnote-ref1" class="footnote-backref">↩︎</a> <a href="#footnote-ref1:1" class="footnote-backref">↩︎</a></p></li></ol></section>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};